-- Sample data for the 'lh-sample' demo workspace (migration 0017): the four sample exports from the finance demo
-- (Lynn Haven's real FY2026 General Fund budget with invented spending, fictional vendors and payments, and
-- invented bank figures), already run through the importer and the flag rules. Generated by loading the files
-- through api/finance.js against a scratch database and dumping the rows.
-- Loads only while the finance tables are still empty, so it can never collide with real uploads. The flags are a
-- snapshot; uploading another file or running the rules in the dashboard recomputes them.
do $sample$
begin
  if exists (select 1 from finance.uploads) or not exists (select 1 from finance.workspaces where id = 'lh-sample') then
    return;
  end if;
end
$sample$;

-- Keep the id sequences ahead of the loaded rows.
do $seq$
declare t text; m bigint;
begin
  foreach t in array array['uploads','budget_lines','disbursements','bank_transactions','bank_recs','flags','activity'] loop
    execute format('select coalesce(max(id), 0) from finance.%I', t) into m;
    if m > 0 then perform setval(pg_get_serial_sequence('finance.' || t, 'id'), m, true); end if;
  end loop;
end
$seq$;
